{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C01","C03","C10","C12","C13","C19","C22","C52","C56","C59","C62","C65","C67","C71","C72","C74"],
  "contradictory_card_ids": ["C64"],
  "prediction_basis_card_ids": ["C01","C03","C10","C12","C13","C19","C22","C52","C56","C59","C62","C65","C67","C71","C72"],
  "claims": [
    {
      "claim": "All L1 gold records report oral bioavailability values or qualitative extents above the F>=20% threshold, with numeric values from about 45% to about 108% and qualitative reports of complete or very good absorption; no L1 record reports F<20%.",
      "card_ids": ["C01","C03","C10","C12","C13","C19","C22"]
    },
    {
      "claim": "L4 intestinal absorption and permeability records for steroid-like molecules show high fraction absorbed (hydrocortisone 89-95% and fa=0.90; prednisolone 95%; corticosterone complete), high permeability (megestrol acetate BCS class II), and complete absorption of danazol solution in dogs; these support the absorption component for a lipophilic steroid query.",
      "card_ids": ["C52","C56","C59","C62"]
    },
    {
      "claim": "L5 gut-wall records show high passive permeability and no significant efflux for steroid-like molecules (hydrocortisone, budesonide, testosterone), with budesonide efflux ratio ~1 and high Papp; this supports the absence of a gut-wall efflux barrier for the query class.",
      "card_ids": ["C65","C67","C71","C72","C74","C75"]
    },
    {
      "claim": "The estrone P-gp efflux record (efflux ratio ~6.6 in MDR1-MDCK, collapsed to 1.2 with GG918) is a single related-steroid observation with uncertain transfer to the query; efflux alone is not threshold-relevant and does not affirm F<20%.",
      "card_ids": ["C64"]
    },
    {
      "claim": "No supplied record provides affirmative threshold-relevant evidence of F<20% for the query; the unfavorable solubility prior is estimated from logP/ionization rather than measured, and the F>=20% threshold may be met with high permeability even if solubility is limited.",
      "card_ids": ["C01","C52","C59","C62","C65","C67"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C64","C65","C66","C67","C68","C69","C70","C71","C72","C73","C74","C75"]
    }
  ],
  "evidence_gaps": [
    "No direct oral versus intravenous bioavailability measurement for the query molecule.",
    "No query-specific dose, formulation, species, or condition data.",
    "L5 records are for other steroid-like molecules (hydrocortisone, budesonide, testosterone, estrone, artemisinin); transfer to the query is indirect.",
    "No direct intestinal metabolism measurement for the query; first-pass metabolism remains uncharacterized.",
    "Query aqueous solubility and dissolution are not experimentally measured; high logP suggests a limitation but does not establish F<20%.",
    "Whether the query is a P-gp substrate is unknown; the estrone efflux observation is not directly transferable."
  ],
  "decision_summary": "Predicted high (F>=20%) because all transferable L1 gold records are above threshold, L4/L5 intestinal absorption and permeability records for steroid-like molecules support high absorption and no significant gut-wall efflux, and no affirmative threshold-relevant evidence indicates F<20%. The estrone P-gp efflux record is a non-threshold counterexample with uncertain transfer. Confidence remains moderate due to lack of direct query-specific F data and unmeasured first-pass metabolism."
}

